INSERT INTO user_products (id, user_id, membership_id, product_id, started_at, ends_at,
                           closed_at, validity_days)
SELECT v.id, u.id, v.membership_id, pr.id, v.started_at, v.ends_at, v.closed_at,
       v.validity_days
  FROM (VALUES
    ('01a14839-be26-7cdd-a34e-29b700c9a5dd'::uuid, 'WilliamB', '01a04ad0-e800-7001-9c4f-5e7ad7000001'::uuid, NULL, '2026-10-17 04:58:26.135852+00'::timestamptz, NULL::timestamptz, '2026-10-17 04:58:26.450727+00'::timestamptz, NULL::integer),
    ('01a14839-bf20-7416-8008-496ce73c6090'::uuid, 'WilliamB', '01a04ad0-e800-7001-9c4f-5e7ad7000001'::uuid, 'MEMBRESIA_BECA', '2026-10-17 04:58:26.450727+00'::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::integer),
    ('01a1419d-0f60-7241-b67c-ba93eeb9f633'::uuid, 'Willy18', '01a04ad0-e800-7001-9c4f-5e7ad7000001'::uuid, NULL, '2026-10-15 22:09:34.479689+00'::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::integer),
    ('01a141d3-f942-7e82-900c-c843eb217f64'::uuid, 'maicol.4494', '01a04ad0-e800-7001-9c4f-5e7ad7000001'::uuid, NULL, '2026-10-15 23:09:33.253948+00'::timestamptz, NULL::timestamptz, NULL::timestamptz, NULL::integer)
       ) AS v (id, username, membership_id, producto, started_at, ends_at, closed_at,
               validity_days)
  JOIN users u ON u.username = v.username
  JOIN semilla_usuarios_nuevos n ON n.id = u.id
  LEFT JOIN products pr ON pr.code = v.producto
 WHERE v.membership_id IS NULL OR EXISTS (SELECT 1 FROM memberships m WHERE m.id = v.membership_id)
ON CONFLICT DO NOTHING;

